/// One agent-kind-specific local CLI runner. Implementations spawn the user's
/// CLI (`claude -p ...`, `agy -p …`, etc.), capture stdout, enforce a timeout,
/// and return an `ExecutorResult`. The dispatcher routes by `agent_kind`.
protocol LocalAgentExecutor {
    /// Logical kind this executor handles. The dispatcher's routing table
    /// keys off this value.
    var agentKind: AgentKind { get }

    func run(
        payload: BehaviorPayload,
        runId: Int,
        timeout: TimeInterval,
        mcp: McpWiring,
        finalizeNudge: String?
    ) async throws -> ExecutorResult
}

/// Typed failure for executor-binary resolution. Lets the dispatcher map
/// "claude not on PATH" to a distinct `exitReason` instead of conflating
/// it with crash/error.
enum ExecutorBinaryError: Error, LocalizedError {
    case notFound(String)

    var errorDescription: String? {
        switch self {
        case let .notFound(name):
            return "\(name) binary not found on PATH"
        }
    }
}

// MARK: - Claude Code

/// Spawn `claude -p <prompt>` as a subprocess. Inherits the user's env
/// (PATH + `ANTHROPIC_API_KEY` are expected to already be set in their
/// shell profile — Owletto never touches the key). The prompt is
/// intentionally dumb: behavior name + event payload + "Please process
/// this." No system prompts, no role descriptions. The CLI brings its own
/// agent loop.
struct ClaudeCodeExecutor: LocalAgentExecutor {
    var agentKind: AgentKind { .claudeCode }

    /// Path to the `claude` binary. Defaults to a PATH lookup at call time.
    let binary: URL?

    init(binary: URL? = nil) {
        self.binary = binary
    }

    func run(
        payload: BehaviorPayload,
        runId: Int,
        timeout: TimeInterval,
        mcp: McpWiring,
        finalizeNudge: String?
    ) async throws -> ExecutorResult {
        let resolvedBinary = try resolveBinary()
        var prompt = Self.buildPrompt(payload: payload, runId: runId)
        if let finalizeNudge, !finalizeNudge.isEmpty {
            prompt += "\n\n---\nFINALIZE NUDGE (prior attempt did not complete the window):\n\(finalizeNudge)\n"
        }
        let started = Date()

        // The gateway's MCP server, scoped to the device token's org. The
        // config carries the bearer — keep it 0600 and delete it after the
        // run.
        let mcpConfigURL = try Self.writeMcpConfig(mcp)
        defer { try? FileManager.default.removeItem(at: mcpConfigURL) }

        let process = Process()
        process.executableURL = resolvedBinary
        process.arguments = Self.buildArguments(
            prompt: prompt,
            config: payload.behavior.execution_config,
            mcpConfigPath: mcpConfigURL.path
        )
        // Inherit the user's environment. lobu CLI auth is credentials.json
        // (same as the menubar) — do not inject LOBU_API_TOKEN.
        var env = ProcessInfo.processInfo.environment
        // GUI apps often get a stripped PATH; ensure common CLI install dirs.
        let extraPath = [
            "\(NSHomeDirectory())/.local/bin",
            "\(NSHomeDirectory())/.bun/bin",
            "/opt/homebrew/bin",
            "/usr/local/bin",
        ].joined(separator: ":")
        let path = env["PATH"] ?? "/usr/bin:/bin"
        if !path.contains("/.local/bin") {
            env["PATH"] = "\(extraPath):\(path)"
        }
        process.environment = env

        let stdoutPipe = Pipe()
        let stderrPipe = Pipe()
        process.standardOutput = stdoutPipe
        process.standardError = stderrPipe
        // No stdin — the CLI gets its prompt via -p.
        process.standardInput = FileHandle.nullDevice

        try process.run()

        // Bounded byte budget: 4 MiB of stdout / 1 MiB of stderr. The CLI's
        // chain-of-thought transcript can easily exceed Process default
        // pipe buffer (64 KiB on macOS); without draining the producer
        // will block on write() and deadlock the SIGTERM-on-timeout path.
        let stdoutCap = 4 * 1024 * 1024
        let stderrCap = 1 * 1024 * 1024
        let stdoutTask = Self.drainPipe(stdoutPipe, capBytes: stdoutCap)
        let stderrTask = Self.drainPipe(stderrPipe, capBytes: stderrCap)

        // Bounded wait. `Process.terminate()` sends SIGTERM; if the child

