        result = try await executor.run(
            payload: job.payload,
            runId: job.run_id,
            timeout: timeout,
            mcp: client.mcpWiring,
            finalizeNudge: finalizeNudge
        )
    } catch {
        // Executor failure — unambiguous, because nothing has been
        // reported yet. Missing binary is a configuration problem, not
        // a crash; keep them distinguishable in the run row so the
        // server / UI can surface "install Claude Code" vs "your CLI
        // segfaulted".
        let reason: String
        if case ExecutorBinaryError.notFound = error {
            reason = "error_message"
        } else {
            reason = "crash"
        }
        await completeWithError(
            client: client,
            workerId: workerId,
            runId: job.run_id,
            error: error.localizedDescription,
            durationMs: 0,
            exitReason: reason
        )
        return
    }

    // Delivery is a separate failure domain from execution. A POST that
    // throws may still have committed the transition server-side, so it
    // must never be reported as an executor error — that would fail a
    // run the server had already granted a resume to.
    guard let report = await deliverExitReport(
        client: client,
        workerId: workerId,
        runId: job.run_id,
        result: result,
        finalizeAttempt: finalizeAttempt
    ) else {
        // Outcome unknown after the retry budget. Leave the run claimed
        // and say nothing: heartbeats stop when this function returns,
        // so the server's heartbeat-stale reaper reclaims it in minutes
        // if the report never landed — and if it did land, the server's
        // own decision stands.
        Log.error(
            .worker,
            "Behavior run=\(job.run_id) exit report undelivered — leaving the run to the server sweep"
        )
        return
    }

    if report.shouldResume {
        finalizeNudge = report.nudge ?? report.error
            ?? "Prior attempt did not call completeWindow. Finalize via lobu CLI or MCP."
        // Follow the server's count rather than incrementing locally:
        // it is the row that decides how many attempts were granted.
        finalizeAttempt = report.attempt ?? (finalizeAttempt + 1)
        Log.info(
            .worker,
            "Behavior run=\(job.run_id) resume "
                + "attempt=\(String(describing: report.attempt)) "
                + "max=\(String(describing: report.max_attempts)) round=\(round + 1)"
        )
        continue
    }
    return
}
