import Foundation

// MARK: - Wire types

/// Decoded shape of `/api/workers/poll` when the server hands us a
/// `run_type='behavior'` job. The `payload` envelope is the only thing the
/// dispatcher passes to the local CLI; everything else is wrapper.
///
/// Server contract: `packages/server/src/worker-api/poll.ts` (behavior
/// short-circuit). The stable internal wire key remains `payload.watcher`.
struct BehaviorJob: Decodable {
    let run_id: Int
    let run_type: String
    let organization_id: String?
    let payload: BehaviorPayload
}

struct BehaviorPayload: Decodable {
    /// Behavior metadata. Product code uses the Behavior name, while the
    /// server's stable internal envelope remains `payload.watcher`.
    let behavior: BehaviorMeta
    let event: BehaviorEvent
    let context: BehaviorContext

    enum CodingKeys: String, CodingKey {
        case watcher
        case event
        case context
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        behavior = try container.decode(BehaviorMeta.self, forKey: .watcher)
        event = try container.decode(BehaviorEvent.self, forKey: .event)
        context = try container.decode(BehaviorContext.self, forKey: .context)
    }

    struct BehaviorMeta: Decodable {
        let id: String
        let name: String?
        let slug: String?
        let agent_kind: String?
        let notification_channel: String?
        let notification_priority: String?
        let execution_config: ExecutionConfig?
        /// The current version's prompt — Behavior instructions, run by
        /// `buildPrompt` as the task. Optional only for decode safety; the
        /// server always ships it (every Behavior has a current version).
        let prompt: String?
        /// The pinned version's extraction_schema (JSON Schema). When present,
        /// `buildPrompt` requires the CLI to end its output with a JSON object
        /// matching it — the server validates the result through the shared
        /// complete_window pipeline and FAILS the run on mismatch. Nil for
        /// schema-less Behaviors (free-form `{"summary": ...}` contract).
        let extraction_schema: AnyJSONValue?
    }

    /// Per-behavior device-worker CLI execution settings. Mirrors the server's
    /// internal `watchers.execution_config` jsonb column.
    /// Every field is optional: a missing key means "use the dispatcher/CLI
    /// default". Field names are snake_case to match the wire payload (the
    /// decoder uses no key-conversion strategy — see the other wire structs).
    struct ExecutionConfig: Decodable {
        /// Wall-clock cap in seconds. Resolved against `defaultTimeout` by the
        /// dispatcher; the executor itself only receives the resolved value.
        let timeout_seconds: Int?
        /// Per-run dollar ceiling. claude only (`--max-budget-usd`); ignored by
        /// executors whose CLI has no cost cap.
        let max_budget_usd: Double?
        /// Model alias/id (`--model`).
        let model: String?
        /// Tool permission mode (`--permission-mode`).
        let permission_mode: String?
        /// Reasoning effort: low|medium|high (`--effort`).
        let effort: String?
    }

    struct BehaviorEvent: Decodable {
        let trigger_event_id: String?
        let fired_at: String
        let payload: [String: AnyJSONValue]?
    }

    /// Whether this run completes as a conversational turn rather than by
    /// closing a window.
    ///
    /// Read from the run's `approved_input`, which poll ships verbatim as
    /// `event.payload` — the same key (`trigger_execution`) the server branches
    /// on in `complete-behavior`, so the device cannot disagree with it. Absent
    /// means a window run: only event-triggered runs carry the key, and
    /// scheduled runs are always windows.
    var isEventTurn: Bool {
        event.payload?["trigger_execution"]?.stringValue == "turn"
    }

    struct BehaviorContext: Decodable {
        let device: BehaviorDevice
        let user: BehaviorUser

        struct BehaviorDevice: Decodable {
            let worker_id: String?
        }

        struct BehaviorUser: Decodable {
            let user_id: String?
        }
    }
}

// MARK: - Executor protocol

/// Result handed back to the dispatcher from a single local-CLI run.
struct ExecutorResult {
    let output: String
    let error: String?
    let exitCode: Int32?
    let exitSignal: String?
    /// Reason the executor finished. Mirrors the wire enum on
    /// `/api/workers/me/runs/:id/complete-behavior` (`ok | error_message |
    /// timeout | oom | crash`). The server stores it on the run row.
    let exitReason: String
    let durationMs: Int
}

/// Gateway MCP endpoint + bearer the executor wires into the spawned CLI so
/// the agent can complete its Behavior run the same way server-side agents
/// do: `query_sdk` (`client.knowledge.read({behavior_id})`) → window_token →
/// `run_sdk` (`client.behaviors.completeWindow(...)`).
struct McpWiring {
    let url: String
    let bearer: String
}

/// Shared Behavior finalize instructions (skill + lobu CLI first; MCP optional).
enum DeviceBehaviorPrompt {
    static func completionContract(
        behaviorId: String,
        runId: Int,
        extractionSchema: AnyJSONValue?
    ) -> String {
        // knowledge.read requires a number; poll ships the id as a string.
        let behaviorIdLiteral: String = {
            if let n = Int(behaviorId.trimmingCharacters(in: .whitespacesAndNewlines)) {
                return String(n)
            }
            return "\"\(behaviorId)\""
        }()
        var schemaLine = ""
        if let schema = extractionSchema,
           JSONSerialization.isValidJSONObject(schema.jsonObject),
           let raw = try? JSONSerialization.data(withJSONObject: schema.jsonObject),
           let s = String(data: raw, encoding: .utf8) {
            schemaLine = """
             `extracted_data` must match this JSON Schema (validated server-side): \(s)
            """
        } else {
            schemaLine = """
             For `extracted_data`, use an object summarizing the result, e.g. \
            {"summary": "<markdown summary of what you found or did>"}.
            """
        }
        return """
        Completion contract (required): this Behavior run is only recorded when completeWindow runs.

        Prefer the local `lobu` CLI (same login as the Owletto menubar — \
        credentials in ~/.config/lobu; no extra auth setup):
          lobu memory exec 'const r = await client.knowledge.read({ behavior_id: \(behaviorIdLiteral) }); return r;'
          # use window_token + content from that result, then:
          lobu memory exec 'await client.behaviors.completeWindow({ behavior_run_id: \(runId), window_token, extracted_data, replace_existing: true }); return { ok: true };'

        MCP is also fine if already wired: query_sdk → knowledge.read, run_sdk → completeWindow.\
        \(schemaLine) \
        Printing a summary alone is NOT enough — if you skip completeWindow the run fails (or resumes once).
        """
    }

    /// Contract for event turns, which have no window to complete. The server
    /// records the run when this process exits cleanly, so calling
    /// completeWindow here would mint a canvas the turn does not have.
    static func turnContract() -> String {
        """
        Completion contract (required): this is a conversational turn, not a window Behavior.

        Do the work and reply. Do NOT call completeWindow, and do not create a canvas — \
        this run has no window. The run is recorded when this process exits cleanly.
        """
    }
}

/// One agent-kind-specific local CLI runner. Implementations spawn the user's
/// CLI (`claude -p ...`, `agy -p …`, etc.), capture stdout, enforce a timeout,
/// and return an `ExecutorResult`. The dispatcher routes by `agent_kind`.
protocol LocalAgentExecutor {
    /// Logical kind this executor handles. The dispatcher's routing table
    /// keys off this value.
    var agentKind: AgentKind { get }

    func run(
        payload: BehaviorPayload,
        runId: Int,
        timeout: TimeInterval,
        mcp: McpWiring,
        finalizeNudge: String?
    ) async throws -> ExecutorResult
}

/// Typed failure for executor-binary resolution. Lets the dispatcher map
/// "claude not on PATH" to a distinct `exitReason` instead of conflating
/// it with crash/error.
enum ExecutorBinaryError: Error, LocalizedError {
    case notFound(String)

    var errorDescription: String? {
        switch self {
        case let .notFound(name):
            return "\(name) binary not found on PATH"
        }
    }
}

// MARK: - Claude Code

/// Spawn `claude -p <prompt>` as a subprocess. Inherits the user's env
/// (PATH + `ANTHROPIC_API_KEY` are expected to already be set in their
/// shell profile — Owletto never touches the key). The prompt is
/// intentionally dumb: behavior name + event payload + "Please process
/// this." No system prompts, no role descriptions. The CLI brings its own
/// agent loop.
struct ClaudeCodeExecutor: LocalAgentExecutor {
    var agentKind: AgentKind { .claudeCode }

    /// Path to the `claude` binary. Defaults to a PATH lookup at call time.
    let binary: URL?

    init(binary: URL? = nil) {
        self.binary = binary
    }

    func run(
        payload: BehaviorPayload,

    static func buildPrompt(payload: BehaviorPayload, runId: Int) -> String {
        let behaviorName = payload.behavior.name ?? payload.behavior.slug ?? payload.behavior.id
        let instructions = payload.behavior.prompt?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        var payloadJSON = "{}"
        if let raw = try? JSONSerialization.data(
            withJSONObject: encodePayloadForJSON(payload),
            options: [.prettyPrinted]
        ), let s = String(data: raw, encoding: .utf8) {
            payloadJSON = s
        }
        return """
        \(instructions)

        ---
        Behavior: \(behaviorName)
        Event payload (context; empty for scheduled runs): \(payloadJSON)

        \(completionContract(payload: payload, runId: runId))
        """
    }

    /// The completion contract appended to a Behavior prompt, chosen by how the
    /// run finishes.
    ///
    /// Window runs complete through `completeWindow`: the CLI has the gateway's
    /// lobu MCP server wired in (--mcp-config) and finalizes the run itself, so
    /// a run whose agent never calls it is resumed and then failed by the
    /// server. The contract is part of the task, not a formatting nicety.
    ///
    /// Event turns have no window — the reply IS the work, and the server
    /// completes the run on a clean exit. Handing them the window contract made
    /// the agent mint a canvas for a conversational turn and complete through
    /// the window path, so the server's no-window branch never ran.
    static func completionContract(payload: BehaviorPayload, runId: Int) -> String {
        if payload.isEventTurn {
            return DeviceBehaviorPrompt.turnContract()
        }
        return DeviceBehaviorPrompt.completionContract(
            behaviorId: payload.behavior.id,
            runId: runId,
            extractionSchema: payload.behavior.extraction_schema
        )
    }

    /// Write the spawned CLI's MCP config: the gateway's lobu MCP server with
    /// the device token as bearer. 0600 — the file carries a credential; the
    /// caller deletes it after the run.
    static func writeMcpConfig(_ mcp: McpWiring) throws -> URL {
        let config: [String: Any] = [
            "mcpServers": [
                "lobu": [
                    "type": "http",
                    "url": mcp.url,
                    "headers": ["Authorization": "Bearer \(mcp.bearer)"],
                ]
            ]
        ]
        let data = try JSONSerialization.data(withJSONObject: config)
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("lobu-behavior-mcp-\(UUID().uuidString).json")
        try data.write(to: url, options: [.atomic])
        try FileManager.default.setAttributes(
            [.posixPermissions: 0o600], ofItemAtPath: url.path
        )
        return url
    }

    /// Assemble the `claude` argv. `-p <prompt>` plus the lobu MCP wiring are
    /// always present; the rest are appended only when the behavior configured
    /// them. Empty strings are treated as unset so a blank UI field never
    /// produces a flag with an empty value. Note: `timeout_seconds` is NOT
    /// mapped here — it's a wall-clock budget the dispatcher enforces by
    /// SIGTERM, not a CLI flag.
    static func buildArguments(
        prompt: String,
        config: BehaviorPayload.ExecutionConfig?,
        mcpConfigPath: String
    ) -> [String] {
        var args = [
            "-p", prompt,
            "--mcp-config", mcpConfigPath,
            // Behavior runs have a narrow completion contract. Do not merge in
            // the user's global MCP configuration (which can add unrelated
            // startup work, credentials, and permission surfaces).
            "--strict-mcp-config",
            // Pre-approve exactly the two completion tools — headless `-p`
            // runs can't answer permission prompts.
            "--allowedTools", "mcp__lobu__query_sdk,mcp__lobu__run_sdk",
        ]
        guard let config else { return args }
        if let model = config.model, !model.isEmpty {
            args += ["--model", model]
        }
        if let budget = config.max_budget_usd, budget > 0 {
            args += ["--max-budget-usd", String(budget)]
        }
        if let mode = config.permission_mode, !mode.isEmpty {
            args += ["--permission-mode", mode]
        }
        if let effort = config.effort, !effort.isEmpty {
            args += ["--effort", effort]
        }
        return args
    }

    /// Hunt for a binary the same way `LocalAgentDetector` does. Avoids
    /// `which`/shell quoting headaches — pure stdlib stat() loop.
    ///
    /// Through the detector's own prefix list, NOT `$PATH` alone. A LaunchAgent
    /// starts with a stripped `$PATH`, so a `claude` or `agy` installed under
    /// `~/.bun/bin` or `/opt/homebrew/bin` was detected, advertised in the UI,
    /// and then failed every run with "binary not found" — the exact disagreement
    /// between detection and execution that `searchPrefixes` documents it exists
    /// to prevent. One list, so the two cannot drift apart again.
    static func locateOnPath(
        _ name: String,
        in dirs: [String] = LocalAgentDetector.searchPrefixes()
    ) -> URL? {
        guard let found = LocalAgentDetector.locate(binary: name, in: dirs) else {
            return nil
        }
        return URL(fileURLWithPath: found)
    }

    /// Drain a Pipe's readable end into a `Data` blob, capped at `capBytes`.
    /// Stops reading once the child closes the pipe (EOF). Excess bytes
    /// past the cap are discarded — we don't want a chatty CLI to blow up
    /// process memory. The returned tuple's `truncated` flag is set when
    /// the cap was hit so the caller can mark the captured output.
    /// Shared with other executors in this file (e.g. `AgyPrintExecutor`).
    fileprivate static func drainPipe(_ pipe: Pipe, capBytes: Int) -> Task<(Data, Bool), Never> {
        Task.detached(priority: .userInitiated) {
            var accumulated = Data()
            var truncated = false
            let handle = pipe.fileHandleForReading
            while true {
                let chunk = handle.availableData
                if chunk.isEmpty { break } // EOF
                if accumulated.count < capBytes {
                    let room = capBytes - accumulated.count
                    if chunk.count > room { truncated = true }
                    accumulated.append(chunk.prefix(room))
                } else {
                    truncated = true
                }
            }
            return (accumulated, truncated)
        }
    }

    /// Await a drain task with a hard wall-clock deadline. If the drain
    /// hasn't finished by then (typically because a grandchild inherited
    /// the pipe and is still alive), force-close the read handle so the
    /// drain's blocking `availableData` returns EOF and the task wraps up.
    fileprivate static func awaitDrain(
        _ task: Task<(Data, Bool), Never>,
        pipe: Pipe,
        deadline: TimeInterval,
        cap: Int
    ) async -> (Data, Bool) {
        let timeoutTask = Task<Void, Never> {
            try? await Task.sleep(nanoseconds: UInt64(deadline * 1_000_000_000))
            // Closing the read handle unblocks the drain's read syscall.
            try? pipe.fileHandleForReading.close()
        }
        let result = await task.value
        timeoutTask.cancel()
        return result
    }

    /// Poll the process until it exits or the timeout lapses. Returns true
    /// when we hit the timeout. Pure polling (50ms tick) is fine here — the
    /// child runs for seconds, not microseconds, and `Process` doesn't
    /// expose a Combine/AsyncSequence for state.
    fileprivate static func waitWithTimeout(process: Process, timeout: TimeInterval) async -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while process.isRunning {
            if Date() > deadline { return true }
            try? await Task.sleep(nanoseconds: 50_000_000)
        }
        return false
    }

    /// Convert the `BehaviorPayload` (which contains `AnyJSONValue` values)
    /// to a plain JSON-encodable dictionary so JSONSerialization can dump
    /// it. We don't go through Codable encode here because
    /// `AnyJSONValue` isn't Encodable in this codebase.
    static func encodePayloadForJSON(_ payload: BehaviorPayload) -> [String: Any] {
        let behavior: [String: Any] = [
            "id": payload.behavior.id,
            "name": payload.behavior.name as Any? ?? NSNull(),
            "slug": payload.behavior.slug as Any? ?? NSNull(),
            "agent_kind": payload.behavior.agent_kind as Any? ?? NSNull(),
        ].compactMapValues { $0 }
        var eventPayload: [String: Any] = [:]
        if let p = payload.event.payload {
            for (k, v) in p { eventPayload[k] = unwrap(v) }
        }
        let event: [String: Any] = [
            "trigger_event_id": payload.event.trigger_event_id as Any? ?? NSNull(),
            "fired_at": payload.event.fired_at,
            "payload": eventPayload,
        ]
        let context: [String: Any] = [
            "device": ["worker_id": payload.context.device.worker_id as Any? ?? NSNull()],
            "user": ["user_id": payload.context.user.user_id as Any? ?? NSNull()],
        ]
        return [
            "behavior": behavior,
            "event": event,
            "context": context,
        ]
    }

    private static func unwrap(_ v: AnyJSONValue) -> Any {
        // Preserve nested objects/arrays — the behavior prompt must carry
        // the original JSON structure verbatim, not flattened `NSNull`
        // placeholders for anything that wasn't a primitive.
        return v.jsonObject
    }
}

