import Foundation

/// Local CLI agents the menu bar knows how to recognize.
///
/// Detection is a **PATH scan**: for each known agent we look for its binary in
/// `$PATH` plus the usual macOS prefixes (Homebrew, `~/.bun/bin`, etc.) and,
/// when found, exec `<binary> --version` to capture a version string. The
/// result is a flat map of `AgentKind → DetectedAgent`.
///
/// This used to be MCP-session based — the bridge queried a `mcp_sessions`
/// table on the gateway and bucketed sessions by `clientInfo.name`. That was
/// the wrong primitive: Behavior execution (lobu#798) spawns the agent CLI as a
/// subprocess, it doesn't open an MCP client. So "is this CLI usable from this
/// Mac" is really "is the binary on disk?", which is what `which` answers.
///
/// Execution (spawn-on-Behavior-fire) lives in `BehaviorDispatcher` — this file's
/// only job is detect + display + persisting the user's default-agent pick.
enum AgentKind: String, CaseIterable, Codable {
    case claudeCode = "claude-code"
    case codex      = "codex"
    case opencode   = "opencode"
    case pi         = "pi"
    /// Google Antigravity CLI (`agy`). Preferred path for device Behaviors
    /// that should bill/use the user's local Google agent subscription, and
    /// the replacement for the retired Gemini CLI kind — Google's own tooling
    /// now points Code Assist users at Antigravity.
    case agy        = "agy"

    /// Executable name to look for on `$PATH`. Picked to match what each
    /// vendor's installer drops in `/usr/local/bin` (or the Homebrew /
    /// `~/.bun/bin` equivalents).
    var binaryName: String {
        switch self {
        case .claudeCode: return "claude"
        case .codex:      return "codex"
        case .opencode:   return "opencode"
        case .pi:         return "pi"
        case .agy:        return "agy"
        }
    }

    var displayName: String {
        switch self {
        case .claudeCode: return "Claude Code"
        case .codex:      return "Codex CLI"
        case .opencode:   return "OpenCode"
        case .pi:         return "pi"
        case .agy:        return "agy (Antigravity)"
        }
    }

    /// Vendor-provided install / docs page. Surfaced as the "Install →" link
    /// on rows where we didn't find the binary so the user has a one-click
    /// path to fix it.
    var installURL: URL {
        switch self {
        case .claudeCode:
            return URL(string: "https://docs.claude.com/en/docs/claude-code/mcp")!
        case .codex:
            return URL(string: "https://github.com/openai/codex")!
        case .opencode:
            return URL(string: "https://opencode.ai/docs/mcp-servers/")!
        case .pi:
            return URL(string: "https://github.com/badlogic/pi-mono")!
        case .agy:
            // Antigravity ships as the `agy` binary via Google's installer;
            // no stable public install URL — point at Gemini CLI docs as a
            // nearby entry, and detection still uses PATH.
            return URL(string: "https://github.com/google-gemini/gemini-cli")!
        }
    }

    /// SF Symbol used in the menubar row icon. Picks lean on each vendor's
    /// brand identity so rows don't all look like the same boilerplate dot:
    /// - `sparkles` — Anthropic's brand around bursts/stars; the Claude name
    ///   itself evokes the sparkle.
    /// - `infinity` — OpenAI's logomark is a loop; Codex sits under OpenAI.
    /// - `chevron.left.forwardslash.chevron.right` — OpenCode is the most
    ///   "raw terminal/code" of the set.
    /// - `circle.grid.cross` — pi, whose tool surface is the most explicitly
    ///   allowlisted (`--tools`) of the set.
    /// - `bolt.fill` — agy / Antigravity.
    var iconName: String {
        switch self {
        case .claudeCode: return "sparkles"
        case .codex:      return "infinity"
        case .opencode:   return "chevron.left.forwardslash.chevron.right"
        case .pi:         return "circle.grid.cross"
        case .agy:        return "bolt.fill"
        }
    }
}

/// One local agent CLI we found on disk. `binaryPath` is the absolute path the
/// PATH scan picked — i.e. exactly what `BehaviorDispatcher` will spawn. We
/// don't bother with last-active / session-id (the previous design's MCP
/// concept); presence on disk is the only signal.
struct DetectedAgent: Equatable {
    let kind: AgentKind
    let binaryPath: String
    /// Best-effort `<binary> --version` capture. `nil` when the binary either
    /// doesn't support `--version`, prints to stderr only, or times out — the
    /// row still renders as detected; we just don't show a version label.
    let version: String?
}

/// Scans `$PATH` (plus the usual macOS prefixes — same set the local Lobu
/// runner uses) for each known `AgentKind`'s binary. Cheap enough to run on
/// every menubar open: at most 4 binaries × ~handful of directories, plus one
/// short-lived `--version` exec per hit. No network.
actor LocalAgentDetector {
    /// Detect every recognized CLI on this Mac. The map is keyed by
    /// `AgentKind`, so callers can render a row per `AgentKind.allCases` and
    /// look up the detected entry (or treat absence as "not installed").
    func detectAll() async -> [AgentKind: DetectedAgent] {
        let prefixes = Self.searchPrefixes()
        var result: [AgentKind: DetectedAgent] = [:]
        for kind in AgentKind.allCases {
            guard let path = Self.locate(binary: kind.binaryName, in: prefixes) else { continue }
            let version = Self.captureVersion(binaryPath: path)
            result[kind] = DetectedAgent(kind: kind, binaryPath: path, version: version)
        }
        return result
    }

    /// The directories we look in, in order. `$PATH` first so a user-installed
    /// shadow of a Homebrew binary still wins; then the standard macOS spots
    /// in case the menu-bar app launched with a stripped `$PATH` (LaunchAgents
    /// often do). Mirrors `LocalLobuRunner.preferredPath` / `locateLobuCLI` so
    /// detection and execution don't disagree.
    static func searchPrefixes() -> [String] {
        var dirs = (ProcessInfo.processInfo.environment["PATH"] ?? "")
            .split(separator: ":")
            .map(String.init)
        dirs.append("\(NSHomeDirectory())/.bun/bin")
        dirs.append("\(NSHomeDirectory())/.local/bin")
        dirs.append("/opt/homebrew/bin")
        dirs.append("/usr/local/bin")
        dirs.append("/usr/bin")
        return dirs
    }

    /// Walk `dirs` looking for an executable file named `binary`. First hit
    /// wins. Returns the absolute path or `nil`.
    static func locate(binary: String, in dirs: [String]) -> String? {
        let fm = FileManager.default
        for dir in dirs where !dir.isEmpty {
            let candidate = "\(dir)/\(binary)"
            if fm.isExecutableFile(atPath: candidate) { return candidate }
        }
        return nil
    }

    /// Exec `<binary> --version` and return the first non-empty line of
    /// combined stdout/stderr. Best-effort: any failure (non-zero exit,
    /// signal, missing pipes, exec error, slow process) collapses to `nil` so
    /// the caller still records the binary as detected. We never throw.
    ///
    /// A 2-second wall clock is plenty for a `--version` call; anything
    /// longer means the binary's misbehaving and we'd rather show "no
    /// version" than block the popover.
    private static func captureVersion(binaryPath: String) -> String? {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: binaryPath)
        process.arguments = ["--version"]
        let pipe = Pipe()
        process.standardOutput = pipe
        process.standardError = pipe
        do {
            try process.run()
        } catch {
            return nil
        }
        // Bound the wait. `waitUntilExit` is blocking; gate it on a deadline
        // and SIGKILL on overrun so a hung binary can't lock the actor.
        let deadline = Date().addingTimeInterval(2.0)
        while process.isRunning && Date() < deadline {
            Thread.sleep(forTimeInterval: 0.05)
        }
        if process.isRunning {
            process.terminate()
            // Give it a moment to clean up before we return.
            Thread.sleep(forTimeInterval: 0.05)
            if process.isRunning { kill(process.processIdentifier, SIGKILL) }
            return nil
        }
        let data = (try? pipe.fileHandleForReading.readToEnd()) ?? Data()
        guard let raw = String(data: data, encoding: .utf8) else { return nil }
        let trimmed = raw
            .split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .first(where: { !$0.isEmpty })
        return trimmed
    }
}

/// `UserDefaults` key for the user's preferred default agent. The Behavior
/// executor (`BehaviorDispatcher`, lobu#798) reads it to pick which CLI to
/// spawn when a Behavior fires without an explicit `agent_kind` override.
/// Lives here so the menubar row and the executor agree on the key name.
enum LobuDefaultAgentSetting {
    static let key = "lobu.defaultAgent"

    static var current: AgentKind? {
        guard let raw = UserDefaults.standard.string(forKey: key) else { return nil }
        return AgentKind(rawValue: raw)
    }

    static func set(_ kind: AgentKind?) {
        if let kind {
            UserDefaults.standard.set(kind.rawValue, forKey: key)
        } else {
            UserDefaults.standard.removeObject(forKey: key)
        }
    }
}

