1	/**
2	 * Behavior-mode `limit` must bound EVERY event source, not just the primary one.
3	 *
4	 * `queryContentData` builds its page descriptor with a hardcoded
5	 * `sourceName: 'content'`, and `wrapQuery` used to apply the LIMIT only when
6	 * `sourceName === page.sourceName`. Every other event source therefore ran
7	 * unbounded — and all of them are returned to the caller under `sources`. So a
8	 * Behavior with more than one source ignored `limit` entirely: the caller asked
9	 * for 2 rows and got the whole window back on the secondary source.
10	 *
11	 * That is what made Behavior 5 unreadable in prod. The sandbox counts every SDK
12	 * result as it crosses the isolate boundary, so an unbounded `sources` blob blew
13	 * the output cap before the script could filter anything — `limit: 1` and
14	 * `limit: 5` failed identically.
15	 *
16	 * The guard: seed more rows than the limit into two distinct feeds, ask for
17	 * fewer, and require BOTH sources to be capped and to report their truncation
18	 * through `sources_page`.
19	 */
20	
21	import { beforeAll, describe, expect, it } from "vitest";
22	import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
23	import {
24		addUserToOrganization,
25		createTestAgent,
26		createTestConnection,
27		createTestEntity,
28		createTestEvent,
29		createTestOrganization,
30		createTestUser,
31	} from "../../setup/test-fixtures";
32	import { TestApiClient } from "../../setup/test-mcp-client";
33	
34	/** Rows seeded per feed. Must exceed PAGE_LIMIT so truncation is observable. */
35	const ROWS_PER_FEED = 3;
36	/** What the caller asks for. Below ROWS_PER_FEED on purpose. */
37	const PAGE_LIMIT = 2;
38	
39	describe("behavior-mode limit bounds every event source", () => {
40		let owner: TestApiClient;
41		let orgId: string;
42		let agentId: string;
43		let entityId: number;
44		let primaryFeedId: number;
45		let secondaryFeedId: number;
46	
47		beforeAll(async () => {
48			await cleanupTestDatabase();
49			const org = await createTestOrganization({ name: "Source Limit Org" });
50			orgId = org.id;
51			const user = await createTestUser({ email: "source-limit@test.com" });
52			await addUserToOrganization(user.id, org.id, "owner");
53			owner = await TestApiClient.for({
54				organizationId: org.id,
55				userId: user.id,
56				memberRole: "owner",
57			});
58			const agent = await createTestAgent({
59				organizationId: org.id,
60				ownerUserId: user.id,
61			});
62			agentId = agent.agentId;
63	
64			const entity = await createTestEntity({
65				name: "Source Limit Target",
66				entity_type: "company",
67				organization_id: orgId,
68				created_by: user.id,
69			});
70			entityId = Number(entity.id);
71	
72			// Two connections, each with its own `default` feed. They are referenced
73			// by feed id rather than `@feed:default` — that ref matches on feed_key,
74			// so both feeds would collapse into a single source and the bug would be
75			// invisible.
76			primaryFeedId = await seedFeed("primary-source-limit", "primary");
77			secondaryFeedId = await seedFeed("secondary-source-limit", "secondary");
78		});
79	
80		/** A connection + its default feed, carrying ROWS_PER_FEED events. */
81		async function seedFeed(slug: string, label: string): Promise<number> {
82			const sql = getTestDb();
83			const connection = await createTestConnection({
84				organization_id: orgId,
85				connector_key: "test.connector",
86				display_name: `Source Limit ${label}`,
87				slug,
88			});
89			const [feed] = await sql<{ id: number | string }[]>`
90	      SELECT id FROM feeds WHERE connection_id = ${connection.id} AND feed_key = 'default'
91	    `;
92			const feedId = Number(feed.id);
93			for (let i = 0; i < ROWS_PER_FEED; i++) {
94				await createTestEvent({
95					entity_id: entityId,
96					organization_id: orgId,
97					connection_id: connection.id,
98					feed_id: feedId,
99					content: `${label} row ${i}`,
100					// Distinct timestamps so keyset ordering is deterministic.
101					occurred_at: new Date(Date.now() - i * 60_000),
102				});
103			}
104			return feedId;
105		}
106	
107		it("caps a secondary event source at the requested limit", async () => {
108			const created = (await owner.behaviors.create({
109				entity_id: entityId,
110				slug: "multi-source-limit",
111				name: "Multi Source Limit",
112				prompt: "Summarize {{content}} alongside {{secondary}}.",
113				agent_id: agentId,
114				sources: [
115					{ name: "content", query: `@feed:${primaryFeedId}` },
116					{ name: "secondary", query: `@feed:${secondaryFeedId}` },
117				],
118			})) as { behavior_id: string };
119	
120			const result = (await owner.knowledge.read({
121				behavior_id: created.behavior_id,
122				since: "today",
123				until: "today",
124				limit: PAGE_LIMIT,
125			})) as {
126				sources: Record<string, unknown[]>;
127				sources_page?: Record<
128					string,
129					{ returned: number; limit: number; has_more: boolean }
130				>;
131			};
132	
133			// The primary source was always bounded — assert it to prove the fixture
134			// really did seed more rows than the limit, so the secondary assertion
135			// below is measuring the bug and not an empty window.
136			expect(result.sources.content).toHaveLength(PAGE_LIMIT);
137	
138			// THE regression. Before the fix this returned all ROWS_PER_FEED rows.
139			expect(result.sources.secondary).toHaveLength(PAGE_LIMIT);
140	
141			// Truncation is reported, not silent — a caller can tell a fully-read
142			// source from a capped one.
143			expect(result.sources_page?.secondary).toEqual({
144				returned: PAGE_LIMIT,
145				limit: PAGE_LIMIT,
146				has_more: true,
147			});
148			expect(result.sources_page?.content).toEqual({
149				returned: PAGE_LIMIT,
150				limit: PAGE_LIMIT,
151				has_more: true,
152			});
153		});
154	
155		it("reports has_more false when a source fits inside the limit", async () => {
156			const created = (await owner.behaviors.create({
157				entity_id: entityId,
158				slug: "multi-source-fits",
159				name: "Multi Source Fits",
160				prompt: "Summarize {{content}} alongside {{secondary}}.",
161				agent_id: agentId,
162				sources: [
163					{ name: "content", query: `@feed:${primaryFeedId}` },
164					{ name: "secondary", query: `@feed:${secondaryFeedId}` },
165				],
166			})) as { behavior_id: string };
167	
168			const roomy = ROWS_PER_FEED + 1;
169			const result = (await owner.knowledge.read({
170				behavior_id: created.behavior_id,
171				since: "today",
172				until: "today",
173				limit: roomy,
174			})) as {
175				sources: Record<string, unknown[]>;
176				sources_page?: Record<
177					string,
178					{ returned: number; limit: number; has_more: boolean }
179				>;
180			};
181	
182			expect(result.sources.secondary).toHaveLength(ROWS_PER_FEED);
183			expect(result.sources_page?.secondary).toEqual({
184				returned: ROWS_PER_FEED,
185				limit: roomy,
186				has_more: false,
187			});
188		});
189	});

